//! Property-name knowledge for `@supports` pre-evaluation.
//!
//! lightningcss's typed parser decided `@supports (prop: value)` leaves by
//! whether it recognized the property. This list carries the same job: it is
//! a curated set of properties the runtime understands or that are broadly
//! implemented in modern engines. Unknown names report unsupported, matching
//! browser behavior.

/// Whether `@supports (name: value)` should report supported at compile time.
pub(crate) fn is_known_property(name: &str) -> bool {
    // Packed storage: one NUL-joined blob plus u16 entry offsets, searched
    // like the sorted pointer-array table it replaced (same compares,
    // smaller footprint in linear memory).
    OFFSETS
        .binary_search_by(|&off| {
            let rest = &BLOB[off as usize..];
            let end = rest.find('\0').unwrap_or(rest.len());
            rest[..end].cmp(name)
        })
        .is_ok()
}

